// Package proto defines the Yousj Mesh control-plane protocol (self-developed).
//
// Design summary (see mesh-design.md supplement):
//   - Every device owns two key pairs, both generated on-device:
//     an Ed25519 identity key (control-plane request signing + SSH identity)
//     and an X25519 WireGuard key (data plane). Private keys never leave the device.
//   - meshd stores only public keys, display names, assigned virtual IPs,
//     exit declarations and invite redemption records.
//   - The network PSK is generated by the creator's client; meshd only stores
//     its SHA-256 hash. The PSK itself travels inside the invite payload.
//   - Control-plane requests are authenticated by an Ed25519 signature over
//     method, path, timestamp and body hash (replay window 5 minutes).
package proto

import (
	"crypto/ed25519"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"fmt"
	"strconv"
	"strings"
	"time"

	"golang.org/x/crypto/curve25519"
)

// Subnet is the phase-1 virtual network range for every mesh network.
const Subnet = "10.99.0.0/24"

// HubIP is reserved for the relay hub inside Subnet.
const HubIP = "10.99.0.1"

// SSHPort is the fixed port of the built-in SSH/SFTP server on each member.
const SSHPort = 2222

// B64 is the encoding used on the wire for keys and signatures.
var B64 = base64.RawURLEncoding

// Identity is a device's full key material (private parts stay on the device).
type Identity struct {
	IDPriv  ed25519.PrivateKey
	IDPub   ed25519.PublicKey
	WGPriv  []byte // 32-byte X25519 private key
	WGPub   []byte // 32-byte X25519 public key
}

// NewIdentity generates fresh device key material.
func NewIdentity() (*Identity, error) {
	pub, priv, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		return nil, err
	}
	wgPriv := make([]byte, 32)
	if _, err := rand.Read(wgPriv); err != nil {
		return nil, err
	}
	wgPub, err := curve25519.X25519(wgPriv, curve25519.Basepoint)
	if err != nil {
		return nil, err
	}
	return &Identity{IDPriv: priv, IDPub: pub, WGPriv: wgPriv, WGPub: wgPub}, nil
}

// DeviceID derives the stable device id from the identity public key.
func DeviceID(idPub ed25519.PublicKey) string {
	h := sha256.Sum256(idPub)
	return hex.EncodeToString(h[:8])
}

// SignRequest produces the signature for a control-plane request.
func SignRequest(priv ed25519.PrivateKey, method, path string, ts int64, body []byte) string {
	msg := CanonicalRequest(method, path, ts, body)
	return B64.EncodeToString(ed25519.Sign(priv, msg))
}

// CanonicalRequest is the exact byte string that gets signed.
func CanonicalRequest(method, path string, ts int64, body []byte) []byte {
	bh := sha256.Sum256(body)
	return []byte(strings.Join([]string{
		strings.ToUpper(method), path, strconv.FormatInt(ts, 10), hex.EncodeToString(bh[:]),
	}, "\n"))
}

// VerifyRequest checks a request signature; ts must be within the replay window.
func VerifyRequest(pub ed25519.PublicKey, method, path, sigB64 string, ts int64, body []byte) error {
	now := time.Now().Unix()
	if ts < now-300 || ts > now+300 {
		return fmt.Errorf("timestamp out of window")
	}
	sig, err := B64.DecodeString(sigB64)
	if err != nil {
		return fmt.Errorf("bad signature encoding")
	}
	if !ed25519.Verify(pub, CanonicalRequest(method, path, ts, body), sig) {
		return fmt.Errorf("signature mismatch")
	}
	return nil
}

// NewToken returns n random bytes as hex (admin tokens, invite codes).
func NewToken(n int) (string, error) {
	b := make([]byte, n)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

// HashPSK is what meshd stores instead of the PSK itself.
func HashPSK(psk []byte) string {
	h := sha256.Sum256(psk)
	return hex.EncodeToString(h[:])
}

// ---- Wire types ----

type HubInfo struct {
	PublicKey string `json:"public_key"`
	Endpoint  string `json:"endpoint"` // host:port
}

type Member struct {
	DeviceID     string `json:"device_id"`
	Name         string `json:"name"`
	VIP          string `json:"vip"`
	WGPub        string `json:"wg_pub"`
	IDPub        string `json:"id_pub"`
	ExitCapable  bool   `json:"exit_capable"`
	ExitOffering bool   `json:"exit_offering"`
	Online       bool   `json:"online"`
	LastSeen     int64  `json:"last_seen"` // unix seconds
}

type CreateNetworkRequest struct {
	Name      string `json:"name"`
	PSKHash   string `json:"psk_hash"`
	PSKForHub string `json:"psk_for_hub"` // sealed to the hub key; meshd cannot read it
}

// MetaResponse is the unauthenticated bootstrap info a client needs before
// it can create a network (the hub key is public information).
type MetaResponse struct {
	Hub HubInfo `json:"hub"`
}

type CreateNetworkResponse struct {
	NetworkID string  `json:"network_id"`
	AdminToken string `json:"admin_token"`
	Hub       HubInfo `json:"hub"`
}

type CreateInviteRequest struct {
	TTLSeconds int `json:"ttl_seconds"`
	MaxUses    int `json:"max_uses"`
}

type CreateInviteResponse struct {
	Code      string `json:"code"`
	ExpiresAt int64  `json:"expires_at"`
}

type JoinRequest struct {
	InviteCode  string `json:"invite_code"`
	Name        string `json:"name"`
	WGPub       string `json:"wg_pub"`
	IDPub       string `json:"id_pub"`
	ExitCapable bool   `json:"exit_capable"`
}

type JoinResponse struct {
	NetworkID   string   `json:"network_id"`
	NetworkName string   `json:"network_name"`
	DeviceID    string   `json:"device_id"`
	VIP         string   `json:"vip"`
	Hub         HubInfo  `json:"hub"`
	Members     []Member `json:"members"`
}

type MembersResponse struct {
	NetworkName string   `json:"network_name"`
	Hub         HubInfo  `json:"hub"`
	Members     []Member `json:"members"`
	Dissolved   bool     `json:"dissolved"`
}

type HeartbeatRequest struct {
	ExitCapable  *bool   `json:"exit_capable,omitempty"`
	ExitOffering *bool   `json:"exit_offering,omitempty"`
	ExitChoice   *string `json:"exit_choice,omitempty"` // device_id of chosen exit; "" = none
}

// InvitePayload is the out-of-band blob (QR / pasted text) a new member uses
// to join. It is produced by an existing member's client, never by meshd,
// because it carries the network PSK in plaintext.
type InvitePayload struct {
	V           int    `json:"v"`
	Coordinator string `json:"coordinator"`
	NetworkID   string `json:"network_id"`
	NetworkName string `json:"network_name"`
	InviteCode  string `json:"invite_code"`
	PSK         string `json:"psk"` // base64 raw-url of 32 bytes
}

// Encode serializes the payload for QR/text transport.
func (p *InvitePayload) Encode() (string, error) {
	raw, err := jsonMarshal(p)
	if err != nil {
		return "", err
	}
	return "yousjmesh://join?d=" + B64.EncodeToString(raw), nil
}

// DecodeInvitePayload parses either the full yousjmesh:// URL or a bare
// base64 blob.
func DecodeInvitePayload(s string) (*InvitePayload, error) {
	s = strings.TrimSpace(s)
	if i := strings.Index(s, "d="); strings.HasPrefix(s, "yousjmesh://") && i >= 0 {
		s = s[i+2:]
	}
	raw, err := B64.DecodeString(s)
	if err != nil {
		return nil, fmt.Errorf("invite payload not decodable: %w", err)
	}
	var p InvitePayload
	if err := jsonUnmarshal(raw, &p); err != nil {
		return nil, fmt.Errorf("invite payload malformed: %w", err)
	}
	if p.NetworkID == "" || p.InviteCode == "" || p.PSK == "" || p.Coordinator == "" {
		return nil, fmt.Errorf("invite payload missing fields")
	}
	return &p, nil
}
